const std = @import("std");

pub fn main() !void {
    var arena = std.heap.ArenaAllocator.init(std.heap.page_allocator);
    defer arena.deinit();

    const allocator = arena.allocator();

    const str = try allocator.dupe(u8, "Hello, Arena!");
    const nums = try allocator.alloc(u32, 5);
    for (0..5) |i| nums[i] = @intCast(i * 10);

    std.debug.print("{s}\n", .{str});
    for (nums) |n| std.debug.print("{} ", .{n});
    std.debug.print("\n", .{});
}
